"""Deterministic checker for a single-label classification task (generated by scripts/build_presets.py).

check(output, reference, input) -> (score, reason). 1.0 if the output names exactly the reference label.
Tolerant of case, whitespace, quotes, code fences, a trailing period, spaces/hyphens instead of underscores,
and a short preamble such as "Label: x". 0.0 if the output names a different label, several labels, or none.
"""
import re

LABELS = [
    "card_arrival",
    "card_linking",
    "exchange_rate",
    "card_payment_wrong_exchange_rate",
    "extra_charge_on_statement",
    "pending_cash_withdrawal",
    "fiat_currency_support",
    "card_delivery_estimate",
    "automatic_top_up",
    "card_not_working",
    "exchange_via_app",
    "lost_or_stolen_card",
    "age_limit",
    "pin_blocked",
    "contactless_not_working",
    "top_up_by_bank_transfer_charge",
    "pending_top_up",
    "cancel_transfer",
    "top_up_limits",
    "wrong_amount_of_cash_received",
    "card_payment_fee_charged",
    "transfer_not_received_by_recipient",
    "supported_cards_and_currencies",
    "getting_virtual_card",
    "card_acceptance",
    "top_up_reverted",
    "balance_not_updated_after_cheque_or_cash_deposit",
    "card_payment_not_recognised",
    "edit_personal_details",
    "why_verify_identity",
    "unable_to_verify_identity",
    "get_physical_card",
    "visa_or_mastercard",
    "topping_up_by_card",
    "disposable_card_limits",
    "compromised_card",
    "atm_support",
    "direct_debit_payment_not_recognised",
    "passcode_forgotten",
    "declined_cash_withdrawal",
    "pending_card_payment",
    "lost_or_stolen_phone",
    "request_refund",
    "declined_transfer",
    "Refund_not_showing_up",
    "declined_card_payment",
    "pending_transfer",
    "terminate_account",
    "card_swallowed",
    "transaction_charged_twice",
    "verify_source_of_funds",
    "transfer_timing",
    "reverted_card_payment?",
    "change_pin",
    "beneficiary_not_allowed",
    "transfer_fee_charged",
    "receiving_money",
    "failed_transfer",
    "transfer_into_account",
    "verify_top_up",
    "getting_spare_card",
    "top_up_by_cash_or_cheque",
    "order_physical_card",
    "virtual_card_not_working",
    "wrong_exchange_rate_for_cash_withdrawal",
    "get_disposable_virtual_card",
    "top_up_failed",
    "balance_not_updated_after_bank_transfer",
    "cash_withdrawal_not_recognised",
    "exchange_charge",
    "top_up_by_card_charge",
    "activate_my_card",
    "cash_withdrawal_charge",
    "card_about_to_expire",
    "apple_pay_or_google_pay",
    "verify_my_identity",
    "country_support"
]


def _norm(s):
    s = s.strip().lower()
    s = re.sub(r"[\s\-/]+", "_", s)
    return s.strip("_.\"'`*:,;")


_NORM = {_norm(l): l for l in LABELS}


def _strip(output):
    out = output or ""
    out = re.sub(r"<think>.*?</think>", "", out, flags=re.S | re.I)
    out = re.sub(r"```[a-zA-Z]*", "", out).replace("```", "")
    return out.strip()


def extract(output):
    out = _strip(output)
    if _norm(out) in _NORM:
        return _NORM[_norm(out)]
    # Also try the last non-empty line, e.g. "Intent:\ncard_arrival".
    lines = [l for l in out.splitlines() if l.strip()]
    if lines:
        last = re.sub(r"^[a-z _]*(label|intent|category|answer|type)\s*[:=]\s*", "", lines[-1].strip(), flags=re.I)
        if _norm(last) in _NORM:
            return _NORM[_norm(last)]
    flat = "_" + re.sub(r"[^a-z0-9]+", "_", out.lower()) + "_"
    found = set()
    for n, l in _NORM.items():
        if "_" + n + "_" in flat:
            found.add(l)
    # Drop labels that are only found as part of a longer found label.
    found = {l for l in found if not any(l != o and _norm(l) in _norm(o) for o in found)}
    if len(found) == 1:
        return found.pop()
    return None if not found else sorted(found)


def check(output, reference, input=""):
    got = extract(output)
    if got is None:
        return 0.0, "no valid label in output: " + repr(_strip(output)[:80])
    if isinstance(got, list):
        return 0.0, "several labels in output: " + ", ".join(got[:4])
    if got == reference:
        return 1.0, "correct: " + got
    return 0.0, "wrong label: got " + got + ", expected " + reference
